  const fl = path.join(core.rootDir(), '.file-locks', core.pathKey(core.canonPath(fs.realpathSync(F))));
  fs.mkdirSync(path.dirname(fl), { recursive: true });
  fs.writeFileSync(fl, `${process.pid}:abandoned`);
  fs.utimesSync(fl, old, old);
