  fs.mkdirSync(proj, { recursive: true });
  fs.writeFileSync(path.join(proj, S + '.jsonl'), JSON.stringify({ message: { role: 'assistant', content: [] } })); // main transcript must exist
  const AG = 'abc123def456';
